responseText:
{
  "title": "Outstanding Documents & Closing Items",
  "components": [
    {
      "use": "Stat",
      "tool": "host_getDashboard",
      "select": "documentsOutstanding",
      "props": {
        "label": "Documents Outstanding",
        "tone": "warn"
      }
    },
    {
      "use": "Stat",
      "tool": "host_getDashboard",
      "select": "clientsMissingDocs",
      "props": {
        "label": "Clients Missing Documents",
        "tone": "warn"
      }
    },
    {
      "use": "Stat",
      "tool": "host_getDashboard",
      "select": "nearestDeadline",
      "props": {
        "label": "Nearest Filing Deadline"
      }
    },
    {
      "use": "DataTable",
      "tool": "host_listDeadlines",
      "props": {
        "caption": "Clients with approaching filing deadlines and missing tax documents",
        "columns": [
          {
            "key": "businessName",
            "label": "Client"
          },
          {
            "key": "filingDeadline",
            "label": "Filing Deadline"
          },
          {
            "key": "status",
            "label": "Status"
          },
          {
            "key": "progress.received",
            "label": "Received Docs"
          },
          {
            "key": "progress.total",
            "label": "Total Required"
          },
          {
            "key": "missingDocKinds",
            "label": "Missing Document Kinds"
          },
          {
            "key": "assignee.name",
            "label": "Assigned Staff"
          }
        ],
        "sortBy": "filingDeadline asc",
        "searchable": true,
        "filterableBy": [
          "status"
        ],
        "paginate": 10
      }
    },
    {
      "use": "DataTable",
      "tool": "host_listActivity",
      "params": {
        "limit": 10
      },
      "props": {
        "caption": "Recent Activity & Document Status Changes",
        "columns": [
          {
            "key": "at",
            "label": "Time"
          },
          {
            "key": "type",
            "label": "Event Type"
          },
          {
            "key": "summary",
            "label": "Summary"
          }
        ],
        "paginate": 5
      }
    }
  ]
}

